describe.each(["tea-rags", "dinopowers", "tea-rags-setup"])("renderClaudePackage(%s)", (name) => {
it("copies the source verbatim (SKILL.md minus codex-description, Markdown with the code tools named), executable bits included", () => {
    const rendered = renderClaudePackage(ROOT, name);
    const src = join(ROOT, PLUGINS_DIR, name);

    expect([...rendered.keys()].sort()).toEqual(
      walk(src)
        .map((file) => relative(src, file))
        .sort(),
    );
    for (const [path, file] of rendered) {
      const source = readFileSync(join(src, path));
      const text = source.toString("utf8");
      const expected = path.endsWith("SKILL.md")
        ? Buffer.from(nameCodeTools(stripFrontmatterKey(text, "codex-description"), CLAUDE_CODE_TOOLS))
        : path.endsWith(".md")
          ? Buffer.from(nameCodeTools(text, CLAUDE_CODE_TOOLS))
          : source;
      expect(file.content.equals(expected), path).toBe(true);
      if (path.endsWith("SKILL.md")) expect(file.content.toString("utf8"), path).not.toMatch(/^codex-description:/m);
      expect(file.mode & 0o111, path).toBe(statSync(join(src, path)).mode & 0o111);
    }
  });
it("names Claude Code's Grep tool / Read tool, never a code tool by role nor ripgrep", () => {
    for (const [path, file] of renderClaudePackage(ROOT, name)) {
      if (!path.endsWith(".md")) continue;
      expect(file.content.toString("utf8"), path).not.toMatch(/default\s+code\s+(?:search|read)\s+tool/i);
    }
  });

describe("macroInvocation rows through the driver slot (research/rustc-driver/RESIDUAL.md R3)", () => {
/** `write!` as the decoder serves a `macroInvocation` row of `std::write`. */
  const STD_WRITE: RustCallSiteDefinition = {
    symbol: "rustc core std::write",
    package: "core",
    inProject: false,
    name: "write",
    kind: "macro",
    packageInProject: false,
  };
  const writeSite = call('write!(f, "x")', null, "write", 9, 4);
it("resolves an in-project macro_rules invocation to the macro's table symbol", () => {
    const t = table(
      def("src/log.rs", "my_log", "my_log", 4, 8, "macro"),
      def("src/log.rs", "my_log", "Logger#my_log", 12, 14),
    );
    const callSites = stubIndex({ "src/main.rs:9:4": inProject("my_log", "src/log.rs", 4, "macro") });
    expect(strategy.attempt(call('my_log!("x")', null, "my_log", 9, 4), ctxWith(t, { callSites }))).toEqual({
      kind: "resolved",
      target: { targetRelPath: "src/log.rs", targetSymbolId: "my_log" },
    });
  });
it("DROPs `write!(f, …)` as external although the project declares `fn write`", () => {
    const t = table(def("src/io.rs", "write", "Sink#write", 3, 6));
    const callSites = stubIndex({ "src/main.rs:9:4": STD_WRITE });
    expect(strategy.attempt(writeSite, ctxWith(t, { callSites }))).toEqual({ kind: "drop" });
  });
it("moves a std macro whose name a project macro_rules shares out of the residual", async () => {
    const t = table(def("src/doc/help.rs", "write", "write", 19, 24, "macro"));
    const without = await facade();
    expect(classifyResolveMiss(writeSite, ctxWith(t), without, t)).toBe("missWithInProjectDef");
    const resolver = await facade({ callSites: stubIndex({ "src/main.rs:9:4": STD_WRITE }) });
    expect(resolver.resolve(writeSite, ctxWith(t))).toBeNull();
    expect(classifyResolveMiss(writeSite, ctxWith(t), resolver, t)).toBe("externalSkipped");
  });

describe("independent Rust source inventory", () => {
it("preserves multiline UTF16 ranges and inner cfg_attr evidence without assuming activation", () => {
    const source = [
      '#![cfg_attr(feature = "x", cfg(unix))]',
      'mod gated { #![cfg(test)] fn f() { let s = "🦀"; target(\n  café()\n); } }',
    ].join("\n");
    const result = inventory(source);
    expect(result.parseErrors).toEqual([]);
    expect(result.sites.map((site) => site.expressionRange)).toEqual([
      rangeOf(source, "target(\n  café()\n)"),
      rangeOf(source, "café()"),
    ]);
    expect(result.sites[0].cfg).toEqual({
      status: "unknown",
      attributes: ['#![cfg_attr(feature = "x", cfg(unix))]', "#![cfg(test)]"],
    });
    expect(result.symbols[0].cfg).toEqual(result.sites[0].cfg);
    expect(result.sites.every((site) => site.provenance === "source")).toBe(true);
  });

